import{_ as n,y as o,a as s,o as i,a2 as t,D as r}from"./chunks/framework.DCcmcJcL.js";const x=JSON.parse('{"title":"Exchange Rates","description":"","frontmatter":{},"headers":[],"relativePath":"configure/exchange-rates-configurations.md","filePath":"configure/exchange-rates-configurations.md","lastUpdated":1789441803000}'),g={name:"configure/exchange-rates-configurations.md"};function h(l,e,c,d,u,p){const a=o("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="exchange-rates" tabindex="-1">Exchange Rates <a class="header-anchor" href="#exchange-rates" aria-label="Permalink to &quot;Exchange Rates&quot;">​</a></h1><p>Bagisto can fetch current exchange rates from an exchange rate service, so prices shown in your other currencies stay correct without entering rates by hand. You can update the rates on demand or on a schedule. Every setting on this screen applies to the whole store.</p><h2 id="general-settings" tabindex="-1">General settings <a class="header-anchor" href="#general-settings" aria-label="Permalink to &quot;General settings&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; General &gt;&gt; Exchange Rates</strong>.</li><li>In <strong>General Settings</strong>, choose the <strong>Default Service</strong>: <strong>Exchange Rates API</strong> (the default) or <strong>Fixer API</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>The default service is the one used by scheduled updates and by the <strong>Update Exchange Rate</strong> button. Enter the API key of that service in its own section.</p><h2 id="exchange-rates-api" tabindex="-1">Exchange Rates API <a class="header-anchor" href="#exchange-rates-api" aria-label="Permalink to &quot;Exchange Rates API&quot;">​</a></h2><p><a href="https://www.exchangerate-api.com" target="_blank" rel="noreferrer">ExchangeRate-API</a> returns the rates for all your currencies in one request. You need an API key from your ExchangeRate-API account.</p><ol><li>Go to <strong>Configure &gt;&gt; General &gt;&gt; Exchange Rates</strong>.</li><li>In <strong>Exchange Rates API</strong>, enter the <strong>API Key</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol><h2 id="fixer-api" tabindex="-1">Fixer API <a class="header-anchor" href="#fixer-api" aria-label="Permalink to &quot;Fixer API&quot;">​</a></h2><p><a href="https://fixer.io" target="_blank" rel="noreferrer">Fixer</a> is asked for the rate of one currency at a time. You need an API key from your Fixer account.</p><ol><li>Go to <strong>Configure &gt;&gt; General &gt;&gt; Exchange Rates</strong>.</li><li>In <strong>Fixer API</strong>, enter the <strong>API Key</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',11)),r(a,{src:"/images/configure/exchange-rates-settings.png",alt:"General Settings, Exchange Rates API and Fixer API sections with placeholder API keys"}),e[1]||(e[1]=t('<p>If an <strong>API Key</strong> is left empty, the store uses the key set for that service in the server&#39;s environment file, if there is one.</p><h2 id="scheduled-import" tabindex="-1">Scheduled import <a class="header-anchor" href="#scheduled-import" aria-label="Permalink to &quot;Scheduled import&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; General &gt;&gt; Exchange Rates</strong>.</li><li>In <strong>Scheduled Import</strong>, switch <strong>Enabled</strong> on. <strong>Frequency</strong> and <strong>Start Time (HH:MM)</strong> appear.</li><li>Choose the <strong>Frequency</strong>: <strong>Daily</strong> (the default), <strong>Weekly</strong>, which runs on Mondays, or <strong>Monthly</strong>, which runs on the first day of the month.</li><li>Enter the <strong>Start Time (HH:MM)</strong> in 24-hour format, such as <code>03:00</code>. The default is <code>00:00</code>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',3)),r(a,{src:"/images/configure/exchange-rates-schedule.png",alt:"Scheduled Import section switched on, updating the rates daily at 03:00"}),e[2]||(e[2]=t('<p>Scheduled updates run on the server&#39;s task scheduler. If the rates don&#39;t update at the set time, ask whoever manages your server to check that the scheduler is running. See <a href="./../getting-started/scheduled-tasks.html">Scheduled Tasks</a>.</p><h2 id="update-the-rates-now" tabindex="-1">Update the rates now <a class="header-anchor" href="#update-the-rates-now" aria-label="Permalink to &quot;Update the rates now&quot;">​</a></h2><ol><li>Go to <strong>Settings &gt;&gt; Exchange Rates</strong>.</li><li>Click <strong>Update Exchange Rate</strong>.</li></ol><p>The rates are fetched from the default service straight away. You can also enter a rate by hand on the same page; see <a href="./../settings/exchange-rates.html">Exchange Rates</a>.</p>',4))])}const m=n(g,[["render",h]]);export{x as __pageData,m as default};
